                  "formaPagamento": "PIX",
                  "nivelClube": "BRONZE",
                  "regiao": "SUDESTE"
                }
                """, 422);

        assertThat(resposta).isEqualTo("{\"erro\":\"CUPOM_INVALIDO\"}");
    }

